-- Create "config_versions" table
CREATE TABLE "config_versions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "hash" character varying NOT NULL, "generation" bigint NOT NULL, "applied_by" character varying NOT NULL, "applied_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create "dashboards" table
CREATE TABLE "dashboards" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "key" character varying NOT NULL, "title" character varying NOT NULL, "visibility" character varying NOT NULL, "position" bigint NOT NULL, "groups" jsonb NULL, "endpoint_keys" jsonb NULL, "allowed_groups" jsonb NULL, PRIMARY KEY ("id"));
-- Create index "dashboards_key_key" to table: "dashboards"
CREATE UNIQUE INDEX "dashboards_key_key" ON "dashboards" ("key");
-- Create "endpoints" table
CREATE TABLE "endpoints" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "key" character varying NOT NULL, "name" character varying NOT NULL, "group_name" character varying NOT NULL DEFAULT '', "type" character varying NOT NULL, "interval_seconds" bigint NOT NULL, "enabled" boolean NOT NULL DEFAULT true, "spec" bytea NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "endpoints_key_key" to table: "endpoints"
CREATE UNIQUE INDEX "endpoints_key_key" ON "endpoints" ("key");
-- Create "workers" table
CREATE TABLE "workers" ("id" character varying NOT NULL, "hostname" character varying NOT NULL, "started_at" timestamptz NOT NULL, "last_heartbeat" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "worker_last_heartbeat" to table: "workers"
CREATE INDEX "worker_last_heartbeat" ON "workers" ("last_heartbeat");
-- Create "endpoint_states" table
CREATE TABLE "endpoint_states" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "status" character varying NOT NULL DEFAULT 'unknown', "version" bigint NOT NULL DEFAULT 0, "consecutive_failures" bigint NOT NULL DEFAULT 0, "consecutive_successes" bigint NOT NULL DEFAULT 0, "last_checked_at" timestamptz NULL, "last_response_time_ms" bigint NOT NULL DEFAULT 0, "last_error" character varying NOT NULL DEFAULT '', "changed_at" timestamptz NOT NULL, "triggered_alerts" jsonb NULL, "endpoint_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "endpoint_states_endpoints_state" FOREIGN KEY ("endpoint_id") REFERENCES "endpoints" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "endpoint_states_endpoint_id_key" to table: "endpoint_states"
CREATE UNIQUE INDEX "endpoint_states_endpoint_id_key" ON "endpoint_states" ("endpoint_id");
-- Create "results" table
CREATE TABLE "results" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "slot" bigint NOT NULL, "checked_at" timestamptz NOT NULL, "success" boolean NOT NULL, "response_time_ms" bigint NOT NULL, "error" character varying NOT NULL DEFAULT '', "conditions" jsonb NULL, "endpoint_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "results_endpoints_results" FOREIGN KEY ("endpoint_id") REFERENCES "endpoints" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "result_checked_at" to table: "results"
CREATE INDEX "result_checked_at" ON "results" ("checked_at");
-- Create index "result_endpoint_id_checked_at" to table: "results"
CREATE INDEX "result_endpoint_id_checked_at" ON "results" ("endpoint_id", "checked_at");
-- Create index "result_endpoint_id_slot" to table: "results"
CREATE UNIQUE INDEX "result_endpoint_id_slot" ON "results" ("endpoint_id", "slot");
-- Create "rollups" table
CREATE TABLE "rollups" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "resolution" character varying NOT NULL, "bucket" timestamptz NOT NULL, "checks" bigint NOT NULL, "successes" bigint NOT NULL, "rt_sum_ms" bigint NOT NULL, "rt_min_ms" bigint NOT NULL, "rt_max_ms" bigint NOT NULL, "endpoint_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "rollups_endpoints_rollups" FOREIGN KEY ("endpoint_id") REFERENCES "endpoints" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "rollup_endpoint_id_resolution_bucket" to table: "rollups"
CREATE UNIQUE INDEX "rollup_endpoint_id_resolution_bucket" ON "rollups" ("endpoint_id", "resolution", "bucket");
-- Create index "rollup_resolution_bucket" to table: "rollups"
CREATE INDEX "rollup_resolution_bucket" ON "rollups" ("resolution", "bucket");
